record.field:
if not self.env.company.country_id:
    warning_records = self.env.company
    warning_count = 0

if not self.env.company.first_payrun_date:
    warning_records = self.env.company
    warning_count = 0

employees_with_anomalies = self.env['hr.employee'].search([
    ('review_state', '=', '3_anomaly'),
    ('company_id', 'in', self.env.companies.ids),
])
if employees_with_anomalies:
    warning_records = employees_with_anomalies
    additional_context = {'search_default_review_state': 'anomaly'}

employees_to_review = self.env['hr.employee'].search([
    ('review_state', '=', '2_to_review'),
    ('company_id', 'in', self.env.companies.ids),
])
if employees_to_review:
    warning_records = employees_to_review
    additional_context = {'search_default_review_state': '2_to_review'}

payslips = self.env['hr.payslip'].search([
    ('id', 'in', active_ids),
    ('company_id', 'in', self.env.companies.ids),
    ('state', '=', 'draft'),
    ('ignore_worked_day_lines', '=', False),
])
warning_details = defaultdict(list)
out_of_contract_payslips = payslips.filtered(lambda p: p._is_out_of_contract())
for payslip in out_of_contract_payslips:
        warning_details[payslip].append({
            'message': _get_payroll_translation('No running contract'),
            'action_text': _get_payroll_translation("Contract"),
            'action': payslip.employee_id._get_records_action(
                name=_get_payroll_translation("Employee"),
                context={**self.env.context, 'version_id': payslip.version_id.id}
            ),
            'level': 'danger',
        })
warning_records = out_of_contract_payslips

leaves = self.env['hr.leave'].search([
    ('payslip_state', '=', 'blocked'),
])
warning_details = defaultdict(list)
warning_records = self.env['hr.leave']
for leave in leaves:
    warning_records |= leave
    warning_details[leave].append({
        'message': _get_payroll_translation("Payslip for the month is already validated."),
        'action_text': _get_payroll_translation("Correct Payslip"),
        'action': leave.action_adjust_corresponding_payslip(),
        'level': 'warning',
    })

payslips = self.env['hr.payslip'].search([
    ('id', 'in', active_ids),
    ('company_id', 'in', self.env.companies.ids),
    ('version_id', '!=', False),
    ('struct_id', '!=', False),
])
similar_payslips = payslips._get_similar_payslips()
warning_details = defaultdict(list)
warning_records = self.env['hr.payslip']
for payslip in payslips:
    key = (payslip.version_id, payslip.struct_id, payslip.date_from, payslip.date_to, payslip.ignore_worked_day_lines)
    duplicates = similar_payslips.get(key, self.env['hr.payslip'])
    if duplicates:
        if payslip.origin_payslip_id:
            duplicates -= payslip.origin_payslip_id + payslip.origin_payslip_id.related_payslip_ids
        if payslip.related_payslip_ids:
            duplicates -= payslip.related_payslip_ids
        if len(duplicates) > 1:
            warning_records |= payslip
            warning_details[payslip].append({
                'message': _get_payroll_translation("Duplicate payslips"),
                'action_text': _get_payroll_translation('Duplicates'),
                'action': duplicates._get_records_action(name=_get_payroll_translation("Duplicate Payslips")),
                'level': 'warning',
            })

warning_records = self.env['hr.payslip']
domain = []
for company in self.env.companies:
    if company.first_payrun_date:
        domain.append([
            ('company_id', '=', company.id),
            ('state', 'in', ['draft', 'validated']),
            ('date_from', '<', company.first_payrun_date),
        ])
if domain:
    if len(domain) == 1:
        final_domain = domain[0]
    else:
        final_domain = ['|'] * (len(domain) - 1)
        for part in domain:
            final_domain += part
    warning_records = self.env['hr.payslip'].search(final_domain)
